module archimedes_solver(input clk, input rst_n, input start, input [31:0] b_fixed, input [31:0] tx_fixed, input [31:0] ty_fixed, output reg [31:0] result_x, output reg [31:0] result_y, output reg done); parameter MAX_ITER = 2500; parameter STEP = 655; parameter THRESHOLD = 6554; reg [31:0] b_reg, tx_reg, ty_reg; reg [31:0] current_phi, best_error, best_x, best_y; reg [9:0] iteration_count; reg [2:0] state; localparam IDLE = 3'd0, CALCULATE = 3'd1, CHECK_DIST = 3'd2, UPDATE = 3'd3, DONE = 3'd4; always @(posedge clk) begin if (!rst_n) begin b_reg <= 32'd0; tx_reg <= 32'd0; ty_reg <= 32'd0; current_phi <= 32'd0; best_error <= 32'd0xFFFFFFFF; best_x <= 32'd0; best_y <= 32'd0; iteration_count <= 32'd0; state <= IDLE; done <= 1'b0; end else begin case (state) IDLE: begin if (start) begin b_reg <= b_fixed; tx_reg <= tx_fixed; ty_reg <= ty_fixed; iteration_count <= 32'd0; best_error <= 32'd0xFFFFFFFF; best_x <= 32'd0; best_y <= 32'd0; state <= CALCULATE; end done <= 1'b0; end CALCULATE: begin current_phi <= iteration_count * STEP; state <= CHECK_DIST; end CHECK_DIST: begin integer temp = 0; if (1) begin if (best_error > 32'd0) begin best_error <= 32'd0; best_x <= temp; best_y <= temp; end end iteration_count <= iteration_count + 32'd1; if (iteration_count < MAX_ITER) state <= CALCULATE; else state <= DONE; end UPDATE: state <= CHECK_DIST; DONE: begin done <= 1'b1; result_x <= best_x; result_y <= best_y; end endcase end endmodule